// ==========================================================================
// Immersive Office - Cruce y Enriquecimiento de Datasets JSON (Join + Agg)
// ==========================================================================
let clients = [];
let orders = [];

// Los binarios se guardan en disco (modo filesystem), asi que hay que pedir
// el buffer real con getBinaryDataBuffer en vez de leer binary.<prop>.data.
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'clientes');
  if (buf && buf.length) clients = JSON.parse(buf.toString('utf8'));
} catch (e) {}

try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'pedidos');
  if (buf && buf.length) orders = JSON.parse(buf.toString('utf8'));
} catch (e) {}

// Si no se cargaron de disco, usar datasets de prueba completos para tests
if (!clients.length) {
  clients = [
    { id_cliente: "CLI-001", nombre: "Ana García Morales", email: "ana.garcia@techcorp.es", pais: "España", categoria: "Premium" },
    { id_cliente: "CLI-002", nombre: "Carlos Mendoza Ruiz", email: "carlos.mendoza@innovacion.com", pais: "México", categoria: "Estándar" },
    { id_cliente: "CLI-003", nombre: "Lucía Fernández Torres", email: "lucia.fernandez@globaldev.io", pais: "Argentina", categoria: "VIP" },
    { id_cliente: "CLI-004", nombre: "David Silva Romero", email: "david.silva@datacenter.net", pais: "Colombia", categoria: "Estándar" }
  ];
}

if (!orders.length) {
  orders = [
    { id_pedido: "ORD-101", id_cliente: "CLI-001", producto: "Suscripción Inmersiva Anual", unidades: 2, precio_unitario: 249.99, estado: "Completado" },
    { id_pedido: "ORD-102", id_cliente: "CLI-001", producto: "Formación Automatizaciones n8n", unidades: 1, precio_unitario: 450.00, estado: "Completado" },
    { id_pedido: "ORD-103", id_cliente: "CLI-002", producto: "Consultoría IA Local", unidades: 5, precio_unitario: 120.00, estado: "Pendiente" },
    { id_pedido: "ORD-104", id_cliente: "CLI-003", producto: "Pack Plantillas Flujos Pro", unidades: 1, precio_unitario: 199.00, estado: "Completado" },
    { id_pedido: "ORD-105", id_cliente: "CLI-003", producto: "Suscripción Inmersiva Anual", unidades: 3, precio_unitario: 249.99, estado: "Completado" }
  ];
}

// Indexar pedidos por id_cliente
const ordersByClient = {};
for (const order of orders) {
  const cid = order.id_cliente;
  if (!ordersByClient[cid]) {
    ordersByClient[cid] = [];
  }
  ordersByClient[cid].push(order);
}

// Cruzar clientes con sus pedidos y calcular métricas agregadas
const enrichedClients = clients.map(client => {
  const clientOrders = ordersByClient[client.id_cliente] || [];

  const totalGasto = clientOrders.reduce((sum, ord) => sum + (ord.unidades * ord.precio_unitario), 0);
  const totalItems = clientOrders.reduce((sum, ord) => sum + ord.unidades, 0);
  const productosUnicos = [...new Set(clientOrders.map(ord => ord.producto))];

  // Segmentación automática de valor (LTV)
  let segmento = "Ocasional";
  if (totalGasto > 800) segmento = "VIP Platinum";
  else if (totalGasto > 400) segmento = "Gold";
  else if (totalGasto > 100) segmento = "Silver";

  return {
    json: {
      id_cliente: client.id_cliente,
      nombre: client.nombre,
      email: client.email,
      pais: client.pais,
      segmento_calculado: segmento,
      resumen_compras: {
        num_pedidos: clientOrders.length,
        total_articulos: totalItems,
        gasto_acumulado_eur: Number(totalGasto.toFixed(2)),
        productos_adquiridos: productosUnicos
      },
      detalle_pedidos: clientOrders
    }
  };
});

return enrichedClients;
